SELECT CASE WHEN duration_sec >= 464 THEN 'high' WHEN duration_sec >= 73 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, SUM(CASE WHEN page = '/search' THEN duration_sec ELSE 0 END) AS search_duration_sec FROM web_events WHERE (duration_sec BETWEEN 248 AND 278 AND page = '/checkout') OR duration_sec < 376 GROUP BY 1 ORDER BY search_duration_sec, duration_sec_bucket;
